from __future__ import annotations
import enum
import uuid
from datetime import datetime, timezone
from sqlalchemy import Boolean, DateTime, Enum, Float, ForeignKey, Index, Integer, JSON, String, Text, UniqueConstraint
from sqlalchemy.orm import Mapped, mapped_column, relationship
from app.core.database import Base


def uid() -> str: return str(uuid.uuid4())
def now() -> datetime: return datetime.now(timezone.utc)


class Timestamps:
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=now)
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), default=now, onupdate=now)
    version: Mapped[int] = mapped_column(Integer, default=1)


class PipelineStage(str, enum.Enum):
    DISCOVERED="DISCOVERED"; RESEARCHED="RESEARCHED"; QUALIFIED="QUALIFIED"; DRAFTED="DRAFTED"; APPROVED="APPROVED"; CONTACTED="CONTACTED"; REPLIED="REPLIED"; MEETING_BOOKED="MEETING_BOOKED"; OPPORTUNITY="OPPORTUNITY"; WON="WON"; LOST="LOST"
class DraftState(str, enum.Enum):
    CREATED="CREATED"; NEEDS_REVIEW="NEEDS_REVIEW"; EDITED="EDITED"; APPROVED="APPROVED"; SEND_PENDING="SEND_PENDING"; SENT="SENT"; FAILED="FAILED"; REJECTED="REJECTED"; CANCELLED="CANCELLED"
class JobState(str, enum.Enum):
    QUEUED="QUEUED"; LEASED="LEASED"; SUCCEEDED="SUCCEEDED"; FAILED="FAILED"; CANCELLED="CANCELLED"
class SubscriberType(str, enum.Enum):
    CORPORATE="VERIFIED_CORPORATE"; INDIVIDUAL="VERIFIED_INDIVIDUAL"; UNKNOWN="UNKNOWN"


